// js/engine/taxonomy-data.js
// CS Lifeline Computer Science Misconception Taxonomy, version 1.0
// Scope: Cambridge IGCSE Computer Science 0478.
//
// Each entry:
//   id           unique, stable identifier (never reuse or renumber)
//   name         short teacher-facing name
//   area         taxonomy area code
//   chapter_id   CS Lifeline chapter (see curriculum.js)
//   topic        topic within the chapter
//   description  the conceptual explanation: what the learner believes and why it is wrong
//   indicators   observable behaviour in answers
//   question_patterns  kinds of question that elicit it
//   causes       plausible underlying causes
//   strategies   corrective teaching strategies
//   related      related misconception IDs
//   evidence     minimum evidence before the engine may call it "demonstrated"
//   legacy_tags  v3 tags that map to this entry (for migrating old records)
//
// The default evidence rule (see misconception.js) applies when `evidence` is omitted.

const E = (min_opportunities = 3, min_errors = 2, min_distinct_questions = 2) =>
  ({ min_opportunities, min_errors, min_distinct_questions });

export const TAXONOMY_VERSION = '1.0';

